#!/usr/bin/env bash
# Creates infra/switch/.env with fresh secrets for the Switch 0.31.0 stack.
# Idempotent: an existing .env is kept (pass --force to regenerate, which
# invalidates every key and the database credentials, so run down.sh -v first).
set -euo pipefail
cd "$(dirname "$0")"
if [[ -f .env && "${1:-}" != "--force" ]]; then
  echo "infra/switch/.env exists, keeping it (use --force to regenerate)"; exit 0
fi
rnd() { openssl rand -hex "${1:-24}"; }
cat > .env <<ENV
# Generated by infra/switch/gen-env.sh on $(date -Iseconds). Do not commit.
SWITCH_REGISTRY=ghcr.io
SWITCH_IMAGE_NAMESPACE=sandbox-quantum
SWITCH_VERSION=0.31.0
COMPOSE_PROFILES=collab,gateway
COMPOSE_PROJECT_NAME=woym-switch
GATEWAY_HOST_PORT=3000
API_HOST_PORT=8000
MATTERMOST_HOST_PORT=8065
POSTGRES_HOST_PORT=55432
SWITCH_BIND_ADDR=127.0.0.1
DB_USER=switch_app
DB_PASSWORD=$(rnd 16)
DB_OWNER_USER=postgres
DB_OWNER_PASSWORD=$(rnd 16)
DB_NAME=switch
TELEMETRY_ENVIRONMENT=local
ID_SERVER_NAME=localhost
AGENT_REGISTRATION_TOKEN=$(rnd 24)
FEATURE_FLAGS_ENABLED=
SECRET_KEYS=k1:$(rnd 32)
JWT_SECRET_KEY=
GATEWAY_ADMIN_EMAIL=admin@switch.local
GATEWAY_ADMIN_PASSWORD=$(rnd 12)
FRONTEND_BASE_URL=http://localhost:3000
MATTERMOST_ADMIN_USER=admin
MATTERMOST_ADMIN_PASSWORD=Adm1n-$(rnd 8)
MATTERMOST_TEAM_NAME=switch
MATTERMOST_USER=user
MATTERMOST_USER_PASSWORD=Us3r-$(rnd 8)
OUTBOUND_ALLOWED_PRIVATE_HOSTS=localhost
ENV
chmod 600 .env
echo "wrote infra/switch/.env"
